-- Data Science Module 10: capstone and final programme competency.
alter table public.data_science_progress drop constraint if exists data_science_progress_module_id_check;alter table public.data_science_progress add constraint data_science_progress_module_id_check check(module_id in('01','02','03','04','05','06','07','08','09','10'));
alter table public.data_science_evidence drop constraint if exists data_science_evidence_module_id_check;alter table public.data_science_evidence add constraint data_science_evidence_module_id_check check(module_id in('01','02','03','04','05','06','07','08','09','10'));
alter table public.data_science_quiz_items drop constraint if exists data_science_quiz_items_module_id_check;alter table public.data_science_quiz_items add constraint data_science_quiz_items_module_id_check check(module_id in('01','02','03','04','05','06','07','08','09','10'));
alter table public.data_science_quiz_attempts drop constraint if exists data_science_quiz_attempts_module_id_check;alter table public.data_science_quiz_attempts add constraint data_science_quiz_attempts_module_id_check check(module_id in('01','02','03','04','05','06','07','08','09','10'));
create or replace function private.data_science_module9_complete(p_user uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.data_science_progress where user_id=p_user and module_id='09'and module_completed_at is not null)$$;
create or replace function private.data_science_module10_lessons_complete(p_user uuid)returns boolean language sql stable security definer set search_path='' as $$select coalesce((lesson_records->>'10-0')::boolean,false)and coalesce((lesson_records->>'10-1')::boolean,false)and coalesce((lesson_records->>'10-2')::boolean,false)from public.data_science_progress where user_id=p_user and module_id='10'$$;
create or replace function private.get_data_science_module10_state()returns table(module_id text,lesson_records jsonb,evidence_submission jsonb,quiz_score numeric,quiz_passed boolean,quiz_attempts integer,module_completed_at timestamptz,module_09_completed boolean,programme_completed boolean)language plpgsql stable security definer set search_path='' as $$declare v_user uuid:=private.data_science_require_user();begin return query select'10'::text,coalesce(p.lesson_records,'{}'::jsonb),(select jsonb_build_object('id',e.id,'content',e.content,'status',e.status,'submitted_at',e.submitted_at)from public.data_science_evidence e where e.user_id=v_user and e.module_id='10'),p.quiz_score,coalesce(p.quiz_passed,false),coalesce(p.quiz_attempts,0),p.module_completed_at,private.data_science_module9_complete(v_user),(p.module_completed_at is not null)from(values(1))seed(n)left join public.data_science_progress p on p.user_id=v_user and p.module_id='10';end$$;
create or replace function public.get_data_science_module10_state()returns table(module_id text,lesson_records jsonb,evidence_submission jsonb,quiz_score numeric,quiz_passed boolean,quiz_attempts integer,module_completed_at timestamptz,module_09_completed boolean,programme_completed boolean)language sql stable security invoker set search_path='' as $$select*from private.get_data_science_module10_state()$$;
create or replace function private.mark_data_science_module10_lesson(p_lesson_index integer)returns void language plpgsql security definer set search_path='' as $$declare v_user uuid:=private.data_science_require_user();v_key text;begin if not private.data_science_module9_complete(v_user)then raise exception'Complete Module 09 before entering Module 10';end if;if p_lesson_index not between 0 and 2 then raise exception'Invalid lesson';end if;v_key:='10-'||p_lesson_index;insert into public.data_science_progress(user_id,module_id,lesson_records,updated_at)values(v_user,'10',jsonb_build_object(v_key,true),now())on conflict(user_id,module_id)do update set lesson_records=public.data_science_progress.lesson_records||excluded.lesson_records,updated_at=now();end$$;
create or replace function public.mark_data_science_module10_lesson(p_lesson_index integer)returns void language sql security invoker set search_path='' as $$select private.mark_data_science_module10_lesson(p_lesson_index)$$;
create or replace function private.submit_data_science_module10_evidence(p_evidence_type text,p_content text)returns bigint language plpgsql security definer set search_path='' as $$declare v_user uuid:=private.data_science_require_user();v_id bigint;begin if not private.data_science_module9_complete(v_user)then raise exception'Complete Module 09 first';end if;if not coalesce(private.data_science_module10_lessons_complete(v_user),false)then raise exception'Complete all three Module 10 lesson records first';end if;if char_length(trim(p_content))not between 100 and 20000 then raise exception'Professional evidence must contain 100 to 20000 characters';end if;insert into public.data_science_evidence(user_id,module_id,evidence_type,content)values(v_user,'10',trim(p_evidence_type),trim(p_content))returning id into v_id;return v_id;end$$;
create or replace function public.submit_data_science_module10_evidence(p_evidence_type text,p_content text)returns bigint language sql security invoker set search_path='' as $$select private.submit_data_science_module10_evidence(p_evidence_type,p_content)$$;
create or replace function private.get_data_science_module10_quiz()returns table(question_id text,question_order integer,stem text,options jsonb)language plpgsql stable security definer set search_path='' as $$declare v_user uuid:=private.data_science_require_user();begin if not private.data_science_module9_complete(v_user)then raise exception'Complete Module 09 first';end if;if not coalesce(private.data_science_module10_lessons_complete(v_user),false)then raise exception'Complete all Module 10 lesson records first';end if;if not exists(select 1 from public.data_science_evidence where user_id=v_user and module_id='10')then raise exception'Submit professional evidence before loading the quiz';end if;return query select q.question_id,q.question_order,q.stem,q.options from public.data_science_quiz_items q where q.module_id='10'and q.active order by q.question_order;end$$;
create or replace function public.get_data_science_module10_quiz()returns table(question_id text,question_order integer,stem text,options jsonb)language sql stable security invoker set search_path='' as $$select*from private.get_data_science_module10_quiz()$$;
create or replace function private.grade_data_science_module10(p_answers jsonb)returns table(score numeric,passed boolean,attempts integer,programme_completed boolean)language plpgsql security definer set search_path='' as $$declare v_user uuid:=private.data_science_require_user();v_questions integer;v_answer_count integer;v_correct integer;v_attempts integer;v_score numeric(5,2);v_passed boolean;v_now timestamptz:=now();begin perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_user::text||':data-science:10',0));if not private.data_science_module9_complete(v_user)then raise exception'Complete Module 09 first';end if;if not coalesce(private.data_science_module10_lessons_complete(v_user),false)then raise exception'Complete all Module 10 lesson records first';end if;if not exists(select 1 from public.data_science_evidence where user_id=v_user and module_id='10'and status in('submitted','accepted'))then raise exception'Submit professional evidence before attempting the quiz';end if;select count(*)into v_attempts from public.data_science_quiz_attempts where user_id=v_user and module_id='10';if v_attempts>=2 then raise exception'Maximum quiz attempts reached';end if;select count(*)into v_questions from public.data_science_quiz_items where module_id='10'and active;select count(*)into v_answer_count from jsonb_object_keys(coalesce(p_answers,'{}'::jsonb));if v_questions=0 then raise exception'Quiz is not configured';end if;if v_answer_count<>v_questions then raise exception'Every active quiz question must be answered exactly once';end if;if exists(select 1 from jsonb_object_keys(p_answers)a where not exists(select 1 from public.data_science_quiz_items q where q.module_id='10'and q.active and q.question_id=a))then raise exception'Answers contain an invalid question';end if;select count(*)into v_correct from public.data_science_quiz_items q where q.module_id='10'and q.active and p_answers?q.question_id and p_answers->>q.question_id=q.correct_option::text;v_score:=round((v_correct::numeric/v_questions)*100,2);v_passed:=v_score>=70;insert into public.data_science_quiz_attempts(user_id,module_id,answers,score,passed)values(v_user,'10',p_answers,v_score,v_passed);insert into public.data_science_progress(user_id,module_id,quiz_score,quiz_passed,quiz_attempts,module_completed_at,updated_at)values(v_user,'10',v_score,v_passed,v_attempts+1,case when v_passed then v_now end,v_now)on conflict(user_id,module_id)do update set quiz_score=greatest(coalesce(public.data_science_progress.quiz_score,0),excluded.quiz_score),quiz_passed=public.data_science_progress.quiz_passed or excluded.quiz_passed,quiz_attempts=excluded.quiz_attempts,module_completed_at=case when excluded.quiz_passed then coalesce(public.data_science_progress.module_completed_at,v_now)else public.data_science_progress.module_completed_at end,updated_at=v_now;return query select v_score::numeric,v_passed,v_attempts+1,v_passed;end$$;
create or replace function public.grade_data_science_module10_quiz(p_answers jsonb)returns table(score numeric,passed boolean,attempts integer,programme_completed boolean)language sql security invoker set search_path='' as $$select*from private.grade_data_science_module10(p_answers)$$;
revoke all on function private.data_science_module9_complete(uuid),private.data_science_module10_lessons_complete(uuid),private.get_data_science_module10_state(),private.mark_data_science_module10_lesson(integer),private.submit_data_science_module10_evidence(text,text),private.get_data_science_module10_quiz(),private.grade_data_science_module10(jsonb)from public,anon,authenticated;grant execute on function private.data_science_module9_complete(uuid),private.data_science_module10_lessons_complete(uuid),private.get_data_science_module10_state(),private.mark_data_science_module10_lesson(integer),private.submit_data_science_module10_evidence(text,text),private.get_data_science_module10_quiz(),private.grade_data_science_module10(jsonb)to authenticated;
revoke all on function public.get_data_science_module10_state(),public.mark_data_science_module10_lesson(integer),public.submit_data_science_module10_evidence(text,text),public.get_data_science_module10_quiz(),public.grade_data_science_module10_quiz(jsonb)from public,anon;grant execute on function public.get_data_science_module10_state(),public.mark_data_science_module10_lesson(integer),public.submit_data_science_module10_evidence(text,text),public.get_data_science_module10_quiz(),public.grade_data_science_module10_quiz(jsonb)to authenticated;
insert into public.data_science_quiz_items(module_id,question_id,question_order,stem,options,correct_option)values('10','ds10-q1',1,'What should a capstone charter begin with?','["A preferred algorithm","A decision, accountable user, affected groups and measurable success criteria","A visual theme","A large dataset"]',1),('10','ds10-q2',2,'What makes an analytical result reproducible?','["A screenshot","Traceable inputs, versioned code and environment, deterministic steps and recorded outputs","A confident presentation","A complex model"]',1),('10','ds10-q3',3,'A model performs well overall but poorly for a vulnerable subgroup. What is required?','["Report only the aggregate","Investigate impact, validate subgroup evidence and apply safeguards","Remove the subgroup from reporting","Deploy without review"]',1),('10','ds10-q4',4,'What is the strongest response when portfolio evidence is limited?','["Hide the limitation","State its consequence and the next test or safeguard","Invent precision","Change the question silently"]',1)on conflict(module_id,question_id)do update set question_order=excluded.question_order,stem=excluded.stem,options=excluded.options,correct_option=excluded.correct_option,active=true;
